  'latestRelease.title': 'Changelog',
  'latestRelease.version': 'Latest version: {version}',
  'latestRelease.itemCount': '{count} updates',
  'latestRelease.section.interaction': 'Tools and interaction',
  'latestRelease.section.canvas': 'Canvas and rendering',
  'latestRelease.section.preferences': 'Preferences and colors',
  'latestRelease.section.maintenance': 'Files and maintenance',
  'latestRelease.item.tools': 'Added ISO drawing, solid and pixel grids, grid snapping, and continuous line constraints; shape and gradient tools now support rounded corners and radial mode.',
  'latestRelease.item.selection': 'Selection, multi-frame, and symmetry transforms now share coordinate and live-preview paths, with selection outlines and conversion to pattern brushes or background presets.',
  'latestRelease.item.layers': 'Added History, smart alignment, and grid alignment; layer, instance, and multi-frame selection, properties, and undo boundaries are more consistent.',
  'latestRelease.item.dragDrop': 'Timelapse export supports MP4, WebM, PNG, and JPG, export scale, slice ranges, cancellation, and opening the output folder.',
  'latestRelease.item.shortcuts': 'Expanded tool-assistance shortcuts and command settings; Quick Command Bar, frame navigation, and view actions preserve user choices.',
  'latestRelease.item.dialogs': 'Dialog defaults, sliders, selects, and property layouts are tighter and more consistent, with new animation, alignment, magnifier, and export settings.',
  'latestRelease.item.rendering': 'Large-canvas adjustment and export paths reuse buffers and preview asynchronously, reducing memory peaks and improving progress and cancellation behavior.',
  'latestRelease.item.preview': 'Preview continuously follows canvas selection, transform, drawing, animation, and transparency changes instead of retaining stale content.',
  'latestRelease.item.mirror': 'Fixed first-stroke and turn misalignment in rotational symmetry, ISO turns, and grid snapping by unifying view, canvas, and selection geometry.',
  'latestRelease.item.input': 'Fixed tablet cursor offsets, stale native cursors, accidental title-bar dragging, and gradient modifiers being mistaken for the hand tool.',
  'latestRelease.item.preferences': 'Added interface animation levels, drag sensitivity, eyedropper magnifier sizes, smart alignment, grid snapping, and more shortcut toggles.',
  'latestRelease.item.colors': 'Improved live color sliders, checkerboard legibility, transparent pattern brushes, overwrite order, and dither-stage controls.',
  'latestRelease.item.cursor': 'Selection information stays beside the origin and updates live with start, end, and size values while remaining aligned through view transforms.',
  'latestRelease.item.format': 'Improved PSD/GIF and slice export, pasted-selection transforms, and indexed-color undo; fixed large-scale export failures and frame overlap.',
  'latestRelease.item.docs': 'Expanded the shared Lua/MSE API, script examples, and API documentation, with additional locale resources and CSP security validation.',
  'latestRelease.item.performance': 'Completed the Beta performance audit and tightened release gates, source fingerprints, and changed-file development checks.',
